// ===================================================
// CONFIG BASE — GESTÃO PESSOAL WAHA + TELEGRAM
// Edite somente este node por cliente/servidor.
// ===================================================
const config = {
  cliente_nome: "NOME_DO_CLIENTE",
  telegram_user_nome: "SEU_NOME_OU_RESPONSAVEL",

  waha: {
    base_url: "http://IP_DA_VPS:3000",
    api_key: "SUA_WAHA_API_KEY",
    session: "default"
  },

  telegram: {
    bot_token: "SEU_BOT_TOKEN_TELEGRAM",
    chat_id: "SEU_CHAT_ID_TELEGRAM"
  },

  monitoramento: {
    timezone: "America/Campo_Grande",
    alertar_quando_ok: false,
    aguardar_pos_restart_segundos: 15
  }
};

return [{ json: { config, started_at: new Date().toISOString() } }];

const previous = $item(0).$node["01 - CONFIG BASE"].json;
const config = previous.config;

const response = $json;
const isError = !!response.error || !!response.message && !!response.statusCode;

let sessions = [];
if (Array.isArray(response)) {
  sessions = response;
} else if (Array.isArray(response.data)) {
  sessions = response.data;
} else if (response.name || response.id || response.session) {
  sessions = [response];
}

const sessionName = String(config.waha.session || "default").toLowerCase();
const sessao = sessions.find(s => String(s.name || s.id || s.session || "").toLowerCase() === sessionName) || sessions[0] || null;
const status = String(sessao?.status || sessao?.state || "").toUpperCase();
const working = !isError && status === "WORKING";

const horario = new Date().toLocaleString("pt-BR", { timeZone: config.monitoramento.timezone });

const text = working
  ? `✅ WAHA OK\n\nCliente: ${config.cliente_nome}\nResponsável: ${config.telegram_user_nome}\nSessão: ${config.waha.session}\nStatus: ${status}\nHorário: ${horario}`
  : `🚨 WAHA CAIU / NÃO ESTÁ WORKING\n\nCliente: ${config.cliente_nome}\nResponsável: ${config.telegram_user_nome}\nSessão: ${config.waha.session}\nStatus encontrado: ${status || "SEM_STATUS"}\nWAHA: ${config.waha.base_url}\nHorário: ${horario}\n\nResposta resumida:\n${JSON.stringify(response).slice(0, 1200)}\n\nAção: verificar sessão no painel WAHA ou rodar restart.`;

return [{ json: { ...previous, sessao, status, working, text } }];
